head.script:
scwin.onpageload = function () {

};

/**
 * 차트 타입이 구성된 Radio 'rad_chartType1'의 이벤트 'onviewchange' 핸들러
 */
scwin.rad_chartType1_onviewchange = function (info) {
    let chartAlias = info.value;
    // Fusionchart 'cht_exam1'의 속성을 설정합니다.
    // radio에 선택된 text를 차트의 caption으로 지정.
    cht_exam1.setChartAttribute({
        "caption": rad_chartType1.getText()
    });

    // Fusionchart 'cht_exam1'의 차트 타입을 변경합니다.
    cht_exam1.changeType(chartAlias);
};

scwin.rad_chartType1_onviewchange = function(info) {
    let chartAlias = info.value;
    // Fusionchart 'cht_exam1'의 속성을 설정합니다.
    // radio에 선택된 text를 차트의 caption으로 지정.
    cht_exam1.setChartAttribute({
        "caption": this.getText()
    });

    // Fusionchart 'cht_exam1'의 차트 타입을 변경합니다.
    cht_exam1.changeType(chartAlias);
};

scwin.btn_exam1_onclick = function(e) {
    // Fusionchart 'cht_exam1'의 Plot 배경색을 지정합니다.
    cht_exam1.setPlotColor(["#ff0000", "#00ff00", "#0000ff", "#00ffff", "ff00ff", "ffff00"]);
    cht_exam2.setPlotColor(["#ff0000", "#00ff00", "#0000ff", "#00ffff", "ff00ff", "ffff00"]);

    // 지정한 속성을 바탕으로 브라우저에 그립니다.
    cht_exam1.draw();
    cht_exam2.draw();
};

	scwin.checkVal1 = function() {
		return document.getElementsByClassName('raphael-group-397-plot-group')[0].children[0].getAttribute('fill') == '#00ff00';
	}		
	scwin.checkVal2 = function() {
		return document.getElementsByClassName('raphael-group-386-plot-group')[0].children[0].getAttribute('fill') == '#ff0000';
	}	
	scwin.checkVal3 = function() {
		return document.getElementsByClassName('raphael-group-434-plot-group')[0].children[2].getAttribute('fill') == '#00ffff';
	}		
	scwin.checkVal4 = function() {
		return document.getElementsByClassName('raphael-group-423-plot-group')[0].children[2].getAttribute('fill') == '#0000ff';
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_exam1').click()");
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
